(3006242, 423359, 23484, '<td valign="top">Way too out of focous.  Did you use a tripod? This would be nice if it were focused more clearly.</td>', 'Way too out of focous.  Did you use a tripod? This would be nice if it were focused more clearly.', '2006-11-06 12:58:01.000000', NULL, 1),
(3006259, 423371, 23484, '<td valign="top">Very cool idea. Great shot. 9</td>', 'Very cool idea. Great shot. 9', '2006-11-06 13:01:05.000000', NULL, 1),
(3006261, 423359, 48389, '<td valign="top">I like your composition but it looks to me like you would benefit from placing the camera on a stable surface such as a tripod. This would get rid of the blur in your photo :o)</td>', 'I like your composition but it looks to me like you would benefit from placing the camera on a stable surface such as a tripod. This would get rid of the blur in your photo :o)', '2006-11-06 13:01:26.000000', NULL, 1),
