INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3009757, 423382, 64175, '<td valign="top">Nice abstract. I have a feeling it might not be appreciated by a number of voters, but I''ll say nicely done. 6.</td>', 'Nice abstract. I have a feeling it might not be appreciated by a number of voters, but I''ll say nicely done. 6.', '2006-11-07 09:02:06.000000', NULL, 1),
(3009758, 423285, 64175, '<td valign="top">I''m getting dizzy.  Nice shot.  7.</td>', 'I''m getting dizzy.  Nice shot.  7.', '2006-11-07 09:02:38.000000', NULL, 1),
(3009760, 423228, 64175, '<td valign="top">Good job keeping the bowl as the stationary point in the photo.  Dogs do like to take down their food in record time. Never understood that, but I know my Golden Retriever can take it out in less than 10 seconds. 6.</td>', 'Good job keeping the bowl as the stationary point in the photo.  Dogs do like to take down their food in record time. Never understood that, but I know my Golden Retriever can take it out in less than 10 seconds. 6.', '2006-11-07 09:04:16.000000', NULL, 1),
(3009839, 423143, 64175, '<td valign="top">Nice.  Funny.  Now, if any one truly DNMC''s this they should be taken out back and beaten with a Nerf bat.</td>', 'Nice.  Funny.  Now, if any one truly DNMC''s this they should be taken out back and beaten with a Nerf bat.', '2006-11-07 09:45:08.000000', NULL, 1),
(3009842, 423039, 64175, '<td valign="top">Beautiful capture.  Nice job. The only thing I wish was different was the hot spot right in the middle/lower right of the image.  Still gets a 10.</td>', 'Beautiful capture.  Nice job. The only thing I wish was different was the hot spot right in the middle/lower right of the image.  Still gets a 10.', '2006-11-07 09:46:17.000000', NULL, 1),
(3009846, 423292, 64175, '<td valign="top">Too much purple for my taste. While the water being purple would be okay, the purple sand just takes it over the top. 5.</td>', 'Too much purple for my taste. While the water being purple would be okay, the purple sand just takes it over the top. 5.', '2006-11-07 09:48:28.000000', NULL, 1),
(3009849, 423239, 15032, '<td valign="top">Nice framing, but the highlights on the left rock are a bit distracting</td>', 'Nice framing, but the highlights on the left rock are a bit distracting', '2006-11-07 09:48:52.000000', NULL, 1),
