(3013060, 423143, 68059, '<td valign="top">If this is DUMC (which I''m not sure it is), I say: GO DUKE!!!</td>', 'If this is DUMC (which I''m not sure it is), I say: GO DUKE!!!', '2006-11-08 06:20:39.000000', NULL, 1),
(3013062, 423029, 68059, '<td valign="top">Now, this is what I would call a composition :)</td>', 'Now, this is what I would call a composition :)', '2006-11-08 06:21:00.000000', NULL, 1),
(3013172, 423203, 63700, '<td valign="top">It''s good to see a photo I recognize.  I''m in K.C. too. :-) 8 + 1bonus pt. =9.</td>', 'It''s good to see a photo I recognize.  I''m in K.C. too. :-) 8 + 1bonus pt. =9.', '2006-11-08 07:22:41.000000', NULL, 1),
(3013729, 423204, 45375, '<td valign="top">very elegant, beautiful use of the light. Reminds me of an Oscar''s portrait or something like that</td>', 'very elegant, beautiful use of the light. Reminds me of an Oscar''s portrait or something like that', '2006-11-08 09:51:46.000000', NULL, 1),
(3013799, 423163, 43565, '<td valign="top">I think that some part of the photo should be in focus.</td>', 'I think that some part of the photo should be in focus.', '2006-11-08 10:02:33.000000', NULL, 1),
(3013821, 423225, 43565, '<td valign="top">I like the texture, but I wish the buidling and pole were in focus.</td>', 'I like the texture, but I wish the buidling and pole were in focus.', '2006-11-08 10:06:06.000000', NULL, 1),
(3013878, 422984, 43565, '<td valign="top">The motion makes her right arm look strange.</td>', 'The motion makes her right arm look strange.', '2006-11-08 10:18:26.000000', NULL, 1),
(3013997, 422686, 22748, '<td valign="top">Hmmm.... doesn''t look like long exposure, since the water droplets and the splashes are so distinct.</td>', 'Hmmm.... doesn''t look like long exposure, since the water droplets and the splashes are so distinct.', '2006-11-08 10:49:48.000000', NULL, 1);
