(3017915, 421139, 42100, '<td valign="top">Very, very cool!  Great composition and colors.  Well done!</td>', 'Very, very cool!  Great composition and colors.  Well done!', '2006-11-09 14:46:56.000000', NULL, 1),
(3017917, 423141, 42100, '<td valign="top">Great mood and efect to this, not to mention very surreal looking.  Very nice!</td>', 'Great mood and efect to this, not to mention very surreal looking.  Very nice!', '2006-11-09 14:47:38.000000', NULL, 1),
