(3019959, 423411, 27399, '<td valign="top">Great colors, very creative/artistic and is a nice application of long exposure, going away from so many other images in this challenge.  10</td>', 'Great colors, very creative/artistic and is a nice application of long exposure, going away from so many other images in this challenge.  10', '2006-11-10 11:29:56.000000', NULL, 1),
(3020008, 420169, 27399, '<td valign="top">Awesome!  Not a particularly easy shot to pull off.  Nice range of colors from the signs, and great exposure leaving the subject in the middle clear/detailed not overblown or too dark.  On closer look, the image might be slightly unlevel (tilting counter clockwise).  Regardless, great photo.  10</td>', 'Awesome!  Not a particularly easy shot to pull off.  Nice range of colors from the signs, and great exposure leaving the subject in the middle clear/detailed not overblown or too dark.  On closer look, the image might be slightly unlevel (tilting counter clockwise).  Regardless, great photo.  10', '2006-11-10 11:46:18.000000', NULL, 1),
(3020010, 421771, 27399, '<td valign="top">Great job turning a beautiful image into an amazing photo.  Colors, framing, exposure, everything is great about this shot.  10.</td>', 'Great job turning a beautiful image into an amazing photo.  Colors, framing, exposure, everything is great about this shot.  10.', '2006-11-10 11:47:15.000000', NULL, 1),
(3020018, 422006, 27399, '<td valign="top">Nice, soft image.  The combination spining wind mills with the two stationary ones adds to the overall quality.  Good framing.</td>', 'Nice, soft image.  The combination spining wind mills with the two stationary ones adds to the overall quality.  Good framing.', '2006-11-10 11:50:00.000000', NULL, 1),
(3020021, 422688, 27399, '<td valign="top">You captured a very "dream" like feeling in this photo.  The subject is great, so are the colors and overall delivery on a good idea.  One of my top photos in this challenge.</td>', 'You captured a very "dream" like feeling in this photo.  The subject is great, so are the colors and overall delivery on a good idea.  One of my top photos in this challenge.', '2006-11-10 11:50:47.000000', NULL, 1),
(3020067, 423274, 42181, '<td valign="top">Nice shot, but could have been very good if the background was less cluttered.</td>', 'Nice shot, but could have been very good if the background was less cluttered.', '2006-11-10 12:14:25.000000', NULL, 1),
(3020071, 423054, 42181, '<td valign="top">Looks more like a pond to me ;-) Nice tranquil shot. 7</td>', 'Looks more like a pond to me ;-) Nice tranquil shot. 7', '2006-11-10 12:16:31.000000', NULL, 1),
