(3020349, 423382, 47704, '<td valign="top">You are obviously a poet, NOT a photographer!</td>', 'You are obviously a poet, NOT a photographer!', '2006-11-10 14:38:55.000000', NULL, 1),
(3020350, 423280, 67006, '<td valign="top">I need to know more about the processing on this photo!  Fasinating and SO well done.</td>', 'I need to know more about the processing on this photo!  Fasinating and SO well done.', '2006-11-10 14:39:10.000000', NULL, 1),
(3020355, 420201, 47704, '<td valign="top">Since I joined DPC I started to hate birds.  I now know why!</td>', 'Since I joined DPC I started to hate birds.  I now know why!', '2006-11-10 14:40:04.000000', NULL, 1),
(3020367, 423380, 67006, '<td valign="top">I''m a beginner, so hope you will share how you created this lovely image.  Did the long exposure bring out more of the colors in the ''deep forest'' shade?  Did you set up the photo, or find it as such?  Excellent!</td>', 'I''m a beginner, so hope you will share how you created this lovely image.  Did the long exposure bring out more of the colors in the ''deep forest'' shade?  Did you set up the photo, or find it as such?  Excellent!', '2006-11-10 14:42:30.000000', NULL, 1),
