INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3020369, 421823, 47704, '<td valign="top">Stevie Wonder says he wants his camera back.</td>', 'Stevie Wonder says he wants his camera back.', '2006-11-10 14:42:49.000000', NULL, 1),
(3020373, 423110, 47704, '<td valign="top">Very nice.  Most of the others in this challenge are total crap!!  I just want to thank you for originality.  You are receiving the only 10 I''m giving in this challenge.  Keep it up.</td>', 'Very nice.  Most of the others in this challenge are total crap!!  I just want to thank you for originality.  You are receiving the only 10 I''m giving in this challenge.  Keep it up.', '2006-11-10 14:43:48.000000', NULL, 1),
(3020379, 423047, 47704, '<td valign="top">Try to focus on the challenge.  How would anyone tell a long exposure on this?    Here''s an idea: pluck a string.....but wait, that''s been done a million times before.  1</td>', 'Try to focus on the challenge.  How would anyone tell a long exposure on this?    Here''s an idea: pluck a string.....but wait, that''s been done a million times before.  1', '2006-11-10 14:45:18.000000', NULL, 1),
(3020381, 422233, 47704, '<td valign="top">2nd worst picture of the challenge.  The only thing that is worse than this is the one that is pitch black with a couple of moving orbs.  Congratulations.  You''re NOT the worst!!</td>', '2nd worst picture of the challenge.  The only thing that is worse than this is the one that is pitch black with a couple of moving orbs.  Congratulations.  You''re NOT the worst!!', '2006-11-10 14:46:14.000000', NULL, 1),
(3020385, 423176, 47704, '<td valign="top">Wow, it''s amazing how you can really tell the long exposure here with all the movement in the picture.....NOT.</td>', 'Wow, it''s amazing how you can really tell the long exposure here with all the movement in the picture.....NOT.', '2006-11-10 14:47:04.000000', NULL, 1),
(3020388, 423246, 47704, '<td valign="top">What does this have to do with Long Exposure?  1</td>', 'What does this have to do with Long Exposure?  1', '2006-11-10 14:47:29.000000', NULL, 1),
(3020390, 423364, 47704, '<td valign="top">I hope the virus your computer has didn''t upload with your entry.  You should try writing.  I''m sure you could sell your camera on eBay!</td>', 'I hope the virus your computer has didn''t upload with your entry.  You should try writing.  I''m sure you could sell your camera on eBay!', '2006-11-10 14:49:00.000000', NULL, 1),
(3020408, 423110, 64446, '<td valign="top">Different &amp; creative. Nicely done!</td>', 'Different & creative. Nicely done!', '2006-11-10 14:52:13.000000', NULL, 1),
(3020419, 421699, 24486, '<td valign="top">I have seen this before on dpc but it is always a cool effect.</td>', 'I have seen this before on dpc but it is always a cool effect.', '2006-11-10 14:55:24.000000', NULL, 1),
(3020425, 423043, 64446, '<td valign="top">It gives the impression the horizon is a bit tilted.</td>', 'It gives the impression the horizon is a bit tilted.', '2006-11-10 14:56:26.000000', NULL, 1),
(3020495, 423064, 64446, '<td valign="top">Crispy colours and nice transition from blue to gold to white. It feels fresh, clean and precious all at the same time.</td>', 'Crispy colours and nice transition from blue to gold to white. It feels fresh, clean and precious all at the same time.', '2006-11-10 15:33:31.000000', NULL, 1),
(3020563, 423184, 52439, '<td valign="top">Incredibly.<br/>Pure and simple.<br/>9</td>', 'Incredibly.Pure and simple.9', '2006-11-10 15:53:52.000000', NULL, 1),
(3020802, 423324, 20941, '<td valign="top">Beautiful shot of the VZ!! Wonderful work!</td>', 'Beautiful shot of the VZ!! Wonderful work!', '2006-11-10 18:18:26.000000', NULL, 1),
(3020813, 423430, 20941, '<td valign="top">Great shot of Gr Central in what must be off peak hours! Fantastic capture of the single soul in the center of light! Wonderful!</td>', 'Great shot of Gr Central in what must be off peak hours! Fantastic capture of the single soul in the center of light! Wonderful!', '2006-11-10 18:27:36.000000', NULL, 1),
(3020988, 422659, 62318, '<td valign="top">Too centered. But a very nice glow.</td>', 'Too centered. But a very nice glow.', '2006-11-10 20:40:01.000000', NULL, 1),
(3020989, 423259, 62318, '<td valign="top">A little too much foreground for me, but still a great shot.</td>', 'A little too much foreground for me, but still a great shot.', '2006-11-10 20:41:41.000000', NULL, 1),
(3020990, 423240, 62318, '<td valign="top">Very stylisitc. Very fun. Color contrast works very well.</td>', 'Very stylisitc. Very fun. Color contrast works very well.', '2006-11-10 20:42:49.000000', NULL, 1),
(3021002, 423425, 62318, '<td valign="top">One of my favorite picutres here, because it is so dynamic.</td>', 'One of my favorite picutres here, because it is so dynamic.', '2006-11-10 20:49:26.000000', NULL, 1),
(3021148, 423360, 62318, '<td valign="top">I like this shot. However, since the wave is frozen, it would seem to indicate this isn''t a long exposure? I''ll give you the benefit of the doubt.</td>', 'I like this shot. However, since the wave is frozen, it would seem to indicate this isn''t a long exposure? I''ll give you the benefit of the doubt.', '2006-11-10 22:37:17.000000', NULL, 1),
(3021211, 422546, 50695, '<td valign="top">glorious, ecstatic, delirious, phallic, centipidenous, soluble, unsolvable, resurrective, sacred, redemptive, unbearable lightness 10</td>', 'glorious, ecstatic, delirious, phallic, centipidenous, soluble, unsolvable, resurrective, sacred, redemptive, unbearable lightness 10', '2006-11-10 23:10:28.000000', NULL, 1),
(3021213, 423256, 50695, '<td valign="top">This is just an awesome capture, an excellent fulfillment of the challenge. I wonder about the black background, though. It''s like a black dress: it does the job, but no points for imagination. Still, when the foreground is so interesting, it might be the most appropriate thing. 9</td>', 'This is just an awesome capture, an excellent fulfillment of the challenge. I wonder about the black background, though. It''s like a black dress: it does the job, but no points for imagination. Still, when the foreground is so interesting, it might be the most appropriate thing. 9', '2006-11-10 23:10:50.000000', NULL, 1),
(3021214, 423250, 50695, '<td valign="top">yes, it''s a gimmick, but what a gimmick! 8</td>', 'yes, it''s a gimmick, but what a gimmick! 8', '2006-11-10 23:10:54.000000', NULL, 1),
(3021215, 423042, 50695, '<td valign="top">way to do a fireworks shot! 8</td>', 'way to do a fireworks shot! 8', '2006-11-10 23:10:58.000000', NULL, 1),
(3021219, 423197, 50695, '<td valign="top">you make it seem so easy, so obvious, like the world is a photograph waiting to be taken. 9</td>', 'you make it seem so easy, so obvious, like the world is a photograph waiting to be taken. 9', '2006-11-10 23:12:01.000000', NULL, 1),
(3021222, 423132, 50695, '<td valign="top">I like how the curling shapes interact with the curls of his hair. He has truly become one with his magic. 8 bump to 9</td>', 'I like how the curling shapes interact with the curls of his hair. He has truly become one with his magic. 8 bump to 9', '2006-11-10 23:13:06.000000', NULL, 1),
(3021223, 421766, 50695, '<td valign="top">That''s either DrAchoo or buckaroo Bonzai. I''d know those ears anywhere. If it''s DrAchoo I''ll give it a 10. Otherwise, I''ll start it at 8. bump to 9</td>', 'That''s either DrAchoo or buckaroo Bonzai. I''d know those ears anywhere. If it''s DrAchoo I''ll give it a 10. Otherwise, I''ll start it at 8. bump to 9', '2006-11-10 23:13:55.000000', NULL, 1),
(3021224, 423239, 50695, '<td valign="top">at first I saw just a motivational poster, but then I was struck by the composition: two heavy forms on each side; prominent, mirrored clumps of brown leaves. This photo has no central prettiness to stop the mind. Instead, the mind travels throughout looking for meaning, finding only the flow of water. You are a student of emptiness. 8</td>', 'at first I saw just a motivational poster, but then I was struck by the composition: two heavy forms on each side; prominent, mirrored clumps of brown leaves. This photo has no central prettiness to stop the mind. Instead, the mind travels throughout looking for meaning, finding only the flow of water. You are a student of emptiness. 8', '2006-11-10 23:14:09.000000', NULL, 1),
(3021225, 423043, 50695, '<td valign="top">that''s a very cool effect. but the shot has an emotional impact as well. 9</td>', 'that''s a very cool effect. but the shot has an emotional impact as well. 9', '2006-11-10 23:14:42.000000', NULL, 1),
(3021226, 423430, 50695, '<td valign="top">Way to isolate your subject! 7</td>', 'Way to isolate your subject! 7', '2006-11-10 23:15:07.000000', NULL, 1),
(3021228, 423098, 50695, '<td valign="top">I love how the tree lights contine the circle! 7</td>', 'I love how the tree lights contine the circle! 7', '2006-11-10 23:15:43.000000', NULL, 1),
(3021229, 423013, 50695, '<td valign="top">I like that I have no sense of the scale of this thing. Sometimes I think it fits on a desktop, sometimes I think it is a rollercoaster. 7</td>', 'I like that I have no sense of the scale of this thing. Sometimes I think it fits on a desktop, sometimes I think it is a rollercoaster. 7', '2006-11-10 23:15:49.000000', NULL, 1),
(3021230, 423279, 50695, '<td valign="top">great composition! I''m guessing this is Alain. 7</td>', 'great composition! I''m guessing this is Alain. 7', '2006-11-10 23:16:18.000000', NULL, 1),
(3021231, 422186, 50695, '<td valign="top">how did you do that??? 9</td>', 'how did you do that??? 9', '2006-11-10 23:16:43.000000', NULL, 1),
(3021232, 423280, 50695, '<td valign="top">a joy to look at. and joy is profound subject matter. 9</td>', 'a joy to look at. and joy is profound subject matter. 9', '2006-11-10 23:17:23.000000', NULL, 1),
(3021233, 423143, 50695, '<td valign="top">lol 7!</td>', 'lol 7!', '2006-11-10 23:17:27.000000', NULL, 1),
(3021235, 423029, 50695, '<td valign="top">two players make for an interesting game. moon to church 8</td>', 'two players make for an interesting game. moon to church 8', '2006-11-10 23:18:23.000000', NULL, 1),
(3021236, 422788, 50695, '<td valign="top">wow. how did you do that?? 7</td>', 'wow. how did you do that?? 7', '2006-11-10 23:18:34.000000', NULL, 1),
(3021237, 423411, 50695, '<td valign="top">this does have a nice abstract quality to it. 7</td>', 'this does have a nice abstract quality to it. 7', '2006-11-10 23:18:41.000000', NULL, 1),
(3021238, 422868, 50695, '<td valign="top">I don''t think the tilt is helping this. It is complex enough without it. Love those long-exposure hues. 7</td>', 'I don''t think the tilt is helping this. It is complex enough without it. Love those long-exposure hues. 7', '2006-11-10 23:19:19.000000', NULL, 1),
(3021239, 419539, 50695, '<td valign="top">Is that a Fritz Lang reference? I''ll give you a 7 just for that.</td>', 'Is that a Fritz Lang reference? I''ll give you a 7 just for that.', '2006-11-10 23:19:28.000000', NULL, 1),
(3021240, 423240, 50695, '<td valign="top">two worlds in one photograph. Nicely done. 8</td>', 'two worlds in one photograph. Nicely done. 8', '2006-11-10 23:19:55.000000', NULL, 1),
(3021242, 423192, 50695, '<td valign="top">a well-worn idea, but a good idea nonetheless. And this is well executed. 7 for now</td>', 'a well-worn idea, but a good idea nonetheless. And this is well executed. 7 for now', '2006-11-10 23:20:15.000000', NULL, 1),
(3021243, 423227, 50695, '<td valign="top">the mundane made spectacular. all the riches of the earth are only as gilded as we perceive them. 9</td>', 'the mundane made spectacular. all the riches of the earth are only as gilded as we perceive them. 9', '2006-11-10 23:21:03.000000', NULL, 1),
(3021244, 423065, 50695, '<td valign="top">it is simultaneously a ghost illusion and the illusion of an old faded photograph. both illusions lend emotional heft to this picture. 9</td>', 'it is simultaneously a ghost illusion and the illusion of an old faded photograph. both illusions lend emotional heft to this picture. 9', '2006-11-10 23:22:09.000000', NULL, 1),
(3021245, 423163, 50695, '<td valign="top">huge energy in those motion lines. it reminds me of Leroy Nieman. 9</td>', 'huge energy in those motion lines. it reminds me of Leroy Nieman. 9', '2006-11-10 23:23:26.000000', NULL, 1),
(3021246, 423361, 50695, '<td valign="top">powerful romantic feeling to this picture. 9</td>', 'powerful romantic feeling to this picture. 9', '2006-11-10 23:24:25.000000', NULL, 1),
(3021247, 422707, 50695, '<td valign="top">eye candy just isn''t scary! But I''ll give you a 7 for the LOL factor.</td>', 'eye candy just isn''t scary! But I''ll give you a 7 for the LOL factor.', '2006-11-10 23:24:40.000000', NULL, 1),
(3021249, 423238, 50695, '<td valign="top">a dignified portrait of a building. 9</td>', 'a dignified portrait of a building. 9', '2006-11-10 23:25:16.000000', NULL, 1),
(3021250, 422523, 50695, '<td valign="top">nice idea to include both banks and emphasize the horizontal flow rather than the vertical. 7</td>', 'nice idea to include both banks and emphasize the horizontal flow rather than the vertical. 7', '2006-11-10 23:25:24.000000', NULL, 1),
(3021253, 421809, 50695, '<td valign="top">it looks like a face! 7</td>', 'it looks like a face! 7', '2006-11-10 23:26:34.000000', NULL, 1),
(3021255, 423246, 50695, '<td valign="top">dynamic composition hinting at the dark side beneath the warm fuzziness. 7</td>', 'dynamic composition hinting at the dark side beneath the warm fuzziness. 7', '2006-11-10 23:26:48.000000', NULL, 1),
(3021256, 422557, 50695, '<td valign="top">I like how part of the appreciation of the photo comes from the title and how the subject is interacting with the photographer. Oh yeah, and it''s funny. 7</td>', 'I like how part of the appreciation of the photo comes from the title and how the subject is interacting with the photographer. Oh yeah, and it''s funny. 7', '2006-11-10 23:26:50.000000', NULL, 1),
(3021261, 423267, 50695, '<td valign="top">a heavy picture, a dark picture. 8</td>', 'a heavy picture, a dark picture. 8', '2006-11-10 23:28:02.000000', NULL, 1),
(3021262, 423329, 50695, '<td valign="top">I love the processing... i.e., I love the "look" of this photo. please share the original when the challenge is done. 8</td>', 'I love the processing... i.e., I love the "look" of this photo. please share the original when the challenge is done. 8', '2006-11-10 23:28:59.000000', NULL, 1),
(3021264, 423254, 50695, '<td valign="top">nice effect and great title. 7 bump to 8</td>', 'nice effect and great title. 7 bump to 8', '2006-11-10 23:29:14.000000', NULL, 1),
(3021267, 422713, 50695, '<td valign="top">exellent fulfillment of the challenge. spectacular picture. 7 or so bump to 8</td>', 'exellent fulfillment of the challenge. spectacular picture. 7 or so bump to 8', '2006-11-10 23:29:33.000000', NULL, 1),
(3021268, 422972, 50695, '<td valign="top">wow, they look like cattails! 7</td>', 'wow, they look like cattails! 7', '2006-11-10 23:29:41.000000', NULL, 1),
(3021271, 423271, 50695, '<td valign="top">Ribbony, but I kinda like it anyway. There''s a meditative stillness to it, and I love that guy on the horizon. 7</td>', 'Ribbony, but I kinda like it anyway. There''s a meditative stillness to it, and I love that guy on the horizon. 7', '2006-11-10 23:30:32.000000', NULL, 1),
(3021274, 423064, 50695, '<td valign="top">I shall call you the alchemist. 9</td>', 'I shall call you the alchemist. 9', '2006-11-10 23:31:18.000000', NULL, 1),
(3021275, 422212, 50695, '<td valign="top">directional smoke and the lighting create a very dramatic effect. 7 bump to 8</td>', 'directional smoke and the lighting create a very dramatic effect. 7 bump to 8', '2006-11-10 23:31:29.000000', NULL, 1),
(3021276, 423184, 50695, '<td valign="top">it looks like you actually went to the moon. This looks like a ribbon to me. 7</td>', 'it looks like you actually went to the moon. This looks like a ribbon to me. 7', '2006-11-10 23:32:13.000000', NULL, 1),
(3021287, 422274, 31637, '<td valign="top">Sweet photo. Not as soothing and definitive as your ribbon winner in the past, but this is still a great light capture. Problem is that in a challenge like long exposure, some ignorants might think you edited your sky and this isnt a long exposure at all. 6</td>', 'Sweet photo. Not as soothing and definitive as your ribbon winner in the past, but this is still a great light capture. Problem is that in a challenge like long exposure, some ignorants might think you edited your sky and this isnt a long exposure at all. 6', '2006-11-10 23:42:47.000000', NULL, 1),
(3021290, 423108, 31637, '<td valign="top">I attempt these shots all the time, they are TOUGH !  I learned that the best way to get a ghost effect depends on the models clothes. In this case, you should of wore white. Great lighting and detailed sky. (6)</td>', 'I attempt these shots all the time, they are TOUGH !  I learned that the best way to get a ghost effect depends on the models clothes. In this case, you should of wore white. Great lighting and detailed sky. (6)', '2006-11-10 23:44:58.000000', NULL, 1),
