(3023774, 423098, 32147, '<td valign="top">london eye, I''m guessing.  Great framing.</td>', 'london eye, I''m guessing.  Great framing.', '2006-11-12 12:25:44.000000', NULL, 1),
(3023783, 423371, 32147, '<td valign="top">great idea!  unique!</td>', 'great idea!  unique!', '2006-11-12 12:34:33.000000', NULL, 1),
(3023821, 423364, 53147, '<td valign="top">I''m giving you a high score just becaue you squeezed both necessary items into your shot. Long exposure? Probably not - at least not in a noticable way, but way to go in probably taking a beating to fulfill your commitments. Well done.</td>', 'I''m giving you a high score just becaue you squeezed both necessary items into your shot. Long exposure? Probably not - at least not in a noticable way, but way to go in probably taking a beating to fulfill your commitments. Well done.', '2006-11-12 13:06:49.000000', NULL, 1),
