(3023912, 422084, 37252, '<td valign="top">nice work slowing the water down. The highlights of the rocks in the upper left corner are a bit blown though. The crop seems a bit too tight to me also, or else use a thinner frame.</td>', 'nice work slowing the water down. The highlights of the rocks in the upper left corner are a bit blown though. The crop seems a bit too tight to me also, or else use a thinner frame.', '2006-11-12 14:26:33.000000', NULL, 1),
(3023918, 422953, 37252, '<td valign="top">night shots can be so difficult - too short of an exposure leaves you with an overly dark image (as I feel this one suffers from). Too long of an exposure result in too soft of focus. I think you got fairly sharp focus, but sadly lost definition in the shadows.</td>', 'night shots can be so difficult - too short of an exposure leaves you with an overly dark image (as I feel this one suffers from). Too long of an exposure result in too soft of focus. I think you got fairly sharp focus, but sadly lost definition in the shadows.', '2006-11-12 14:28:55.000000', NULL, 1),
(3023919, 423141, 37252, '<td valign="top">nice pp - the glow really defines this image</td>', 'nice pp - the glow really defines this image', '2006-11-12 14:30:13.000000', NULL, 1),
(3023927, 420750, 12578, '<td valign="top">Would love to have seen this with some motion instead of a just above par run of the mill london eye night shot.</td>', 'Would love to have seen this with some motion instead of a just above par run of the mill london eye night shot.', '2006-11-12 14:35:01.000000', NULL, 1),
