(3025622, 423239, 58055, '<td valign="top">Classy shot, well done Tom</td>', 'Classy shot, well done Tom', '2006-11-13 05:49:05.000000', NULL, 0),
(3025624, 421766, 61191, '<td valign="top">Oh! Only 5.84!! It''s a shame voters didn''t appreciate your shot: often people only look 1 sec at shots and don''t think about their creation process. Love your story about the shooting. When I saw your shot during voting I couldn''t image that someone was so crazy to tape his camera onto the hood - now I know you really did. Great! :)</td>', 'Oh! Only 5.84!! It''s a shame voters didn''t appreciate your shot: often people only look 1 sec at shots and don''t think about their creation process. Love your story about the shooting. When I saw your shot during voting I couldn''t image that someone was so crazy to tape his camera onto the hood - now I know you really did. Great! :)', '2006-11-13 05:50:11.000000', NULL, 0),
(3025640, 422006, 47721, '<td valign="top">Hey Keith,<br/> <br/>A weel deserved ribbon.... beautiful....</td>', 'Hey Keith, A weel deserved ribbon.... beautiful....', '2006-11-13 06:14:52.000000', NULL, 0),
