(3028765, 421711, 22301, '<td valign="top">Mr. Funk, great job, I tried something similar a few months ago, but had no strobes or flashes to use. This is great work and glad you put in the effort, congrats on your 16th place finish.</td>', 'Mr. Funk, great job, I tried something similar a few months ago, but had no strobes or flashes to use. This is great work and glad you put in the effort, congrats on your 16th place finish.', '2006-11-13 23:02:44.000000', NULL, 0),
(3028773, 422212, 22301, '<td valign="top">I really like how you used the long expoure to capture the presence of the wind, well don and congrats on your 17th place on your second entry!</td>', 'I really like how you used the long expoure to capture the presence of the wind, well don and congrats on your 17th place on your second entry!', '2006-11-13 23:05:19.000000', NULL, 0),
(3028776, 423117, 22301, '<td valign="top">Great job Kris, I think you had just the right amount of blur and didn''t over do it with a longer exposure. Congrats on your top 20 finish.</td>', 'Great job Kris, I think you had just the right amount of blur and didn''t over do it with a longer exposure. Congrats on your top 20 finish.', '2006-11-13 23:07:31.000000', NULL, 0),
(3028783, 423098, 22301, '<td valign="top">Love the Deep blues and the motion blur, exactly what this challenge description wanted.</td>', 'Love the Deep blues and the motion blur, exactly what this challenge description wanted.', '2006-11-13 23:08:37.000000', NULL, 0),
(3028789, 423430, 22301, '<td valign="top">I was one your tens, I wish this woould have ribboned or atleast been on the first page. Congrats on a high finish in the high scoring challenge.</td>', 'I was one your tens, I wish this woould have ribboned or atleast been on the first page. Congrats on a high finish in the high scoring challenge.', '2006-11-13 23:10:43.000000', NULL, 0),
